import{_ as t,o,c as s,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Input-Selection-Options.md","filePath":"manual-en/Input-Selection-Options.md","lastUpdated":1785684581000}'),a={name:"manual-en/Input-Selection-Options.md"};function i(c,e,p,l,d,r){return o(),s("div",null,[...e[0]||(e[0]=[n('<h3 id="_19-6-input-selection-options" tabindex="-1">19.6 Input Selection Options <a class="header-anchor" href="#_19-6-input-selection-options" aria-label="Permalink to &quot;19.6 Input Selection Options&quot;">​</a></h3><p>The <code>dir</code> and <code>convert</code> commands, by default, operate on all of the objects in the source SPV file, except for objects that are not visible in the output viewer window. The user may specify these options to select a subset of the input objects. When multiple options are used, only objects that satisfy all of them are selected:</p><p>--select=[^]class…</p><p>Include only objects of the given class; with leading ‘^’, include only objects not in the class. Use commas to separate multiple classes. The supported classes are:</p><blockquote><p><code>charts headings logs models tables texts trees warnings outlineheaders pagetitle notes unknown other</code></p></blockquote><p>Use --select=help to print this list of classes.</p><p>--commands=[^]command… --subtypes=[^]subtype… --labels=[^]label…</p><p>Include only objects with the specified command, subtype, or label. With a leading ‘^’, include only the objects that do not match. Multiple values may be specified separated by commas. An asterisk at the end of a value acts as a wildcard.</p><p>The --command option matches command identifiers, case insensitively. All of the objects produced by a single command use the same, unique command identifier. Command identifiers are always in English regardless of the language used for output. They often differ from the command name in PSPP syntax. Use the <code>pspp-output</code> program’s <code>dir</code> command to print command identifiers in particular output.</p><p>The --subtypes option matches particular tables within a command, case insensitively. Subtypes are not necessarily unique: two commands that produce similar output tables may use the same subtype. Subtypes are always in English and <code>dir</code> will print them.</p><p>The --labels option matches the labels in table output (that is, the table titles). Labels are affected by the output language, variable names and labels, split file settings, and other factors.</p><p>--nth-commands=n…</p><p>Include only objects from the nth command that matches --command (or the nth command overall if --command is not specified), where n is 1 for the first command, 2 for the second, and so on.</p><p>--instances=instance…</p><p>Include the specified instance of an object that matches the other criteria within a single command. The instance may be a number (1 for the first instance, 2 for the second, and so on) or <code>last</code> for the last instance.</p><p>--show-hidden</p><p>Include hidden output objects in the output. By default, they are excluded.</p><p>--or</p><p>Separates two sets of selection options. Objects selected by either set of options are included in the output.</p><p>The following additional input selection options are intended mainly for use by PSPP developers:</p><p>--errors</p><p>Include only objects that cause an error when read. With the <code>convert</code> command, this is most useful in conjunction with the --force option.</p><p>--members=member…</p><p>Include only the objects that include a listed Zip file member. More than one name may be included, comma-separated. The members in an SPV file may be listed with the <code>dir</code> command by adding the --show-members option or with the <code>zipinfo</code> program included with many operating systems. Error messages that <code>pspp-output</code> prints when it reads SPV files also often include member names.</p><p>--member-names</p><p>Displays the name of the Zip member or members associated with each object just above the object itself.</p>',26)])])}const u=t(a,[["render",i]]);export{h as __pageData,u as default};
